package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct { // 01 LOAN-REC, 21 bytes
	LrAcct      string          // PIC X(6) @0 len=6
	LrPrincipal decimal.Decimal // PIC 9(7)V99 @6 len=9
	LrRate      decimal.Decimal // PIC 9(2)V99 @15 len=4
	LrYears     int64           // PIC 9(2) @19 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                           // PIC X len=1 = "N"
var WsInterest decimal.Decimal = decimal.NewFromInt(0) // PIC 9(9)V99 len=11 = 0
var WsTotal decimal.Decimal = decimal.NewFromInt(0)   // PIC 9(11)V99 len=13 = 0
var WsCount int64 = 0                                  // PIC 9(5) len=5 = 0
var WsPrinEd string                                    // PIC Z,ZZZ,ZZ9.99 len=12
var WsIntEd string                                     // PIC ZZZ,ZZZ,ZZ9.99 len=14
var WsTotalEd string                                   // PIC ZZ,ZZZ,ZZZ,ZZ9.99 len=17

var loanRec LoanRec
var loanFile *os.File
var scanner *bufio.Scanner

func inputDone() bool { return WsEofFlag == "Y" }

func pow10Decimal(n int) decimal.Decimal {
	if n <= 0 {
		return decimal.NewFromInt(1)
	}
	return decimal.NewFromInt(1).Shift(int32(n))
}

func formatIntWithLeadingZeros(d decimal.Decimal, width int) string {
	if width <= 0 {
		return ""
	}
	s := d.Truncate(0).String()
	// Remove possible "-"
	if len(s) > 0 && s[0] == '-' {
		s = s[1:]
	}
	// If decimal produced "-0" etc
	if s == "" {
		s = "0"
	}
	if len(s) > width {
		s = s[len(s)-width:]
	}
	if len(s) < width {
		s = strings.Repeat("0", width-len(s)) + s
	}
	return s
}

func formatEdited(value decimal.Decimal, picture string) string {
	dotPos := strings.Index(picture, ".")
	intPlaceCount := 0
	decPlaceCount := 0
	if dotPos == -1 {
		for _, ch := range picture {
			if ch == 'Z' || ch == '9' {
				intPlaceCount++
			}
		}
	} else {
		for i, ch := range picture {
			if ch == 'Z' || ch == '9' {
				if i < dotPos {
					intPlaceCount++
				} else {
					decPlaceCount++
				}
			}
		}
	}

	signNeg := value.Sign() < 0
	absVal := value
	if signNeg {
		absVal = absVal.Neg()
	}
	absValTrunc := absVal.Truncate(int32(decPlaceCount))
	scaledTrunc := absValTrunc.Shift(int32(decPlaceCount)).Truncate(0)
	totalDigits := intPlaceCount + decPlaceCount
	mod := pow10Decimal(totalDigits)
	if scaledTrunc.Cmp(mod) >= 0 {
		scaledTrunc = scaledTrunc.Mod(mod)
	}
	var integerPart decimal.Decimal
	var decimalPart decimal.Decimal
	if decPlaceCount > 0 {
		powDec := pow10Decimal(decPlaceCount)
		integerPart = scaledTrunc.Div(powDec).Truncate(0)
		decimalPart = scaledTrunc.Mod(powDec)
	} else {
		integerPart = scaledTrunc
		decimalPart = decimal.NewFromInt(0)
	}

	intStr := formatIntWithLeadingZeros(integerPart, intPlaceCount)
	decStr := formatIntWithLeadingZeros(decimalPart, decPlaceCount)

	// fill output with digits
	output := make([]rune, len(picture))
	for i, ch := range picture {
		output[i] = ch
	}
	pInt := 0
	pDec := 0
	for i, ch := range picture {
		if ch == 'Z' || ch == '9' {
			if dotPos == -1 || i < dotPos {
				if pInt < len(intStr) {
					output[i] = rune(intStr[pInt])
					pInt++
				}
			} else {
				if pDec < len(decStr) {
					output[i] = rune(decStr[pDec])
					pDec++
				}
			}
		}
	}

	// suppression for integer part
	intEnd := len(picture)
	if dotPos != -1 {
		intEnd = dotPos
	}
	inSuppression := true
	for i := 0; i < intEnd; i++ {
		picCh := rune(picture[i])
		outCh := output[i]
		if picCh == 'Z' {
			if inSuppression {
				if outCh == '0' {
					output[i] = ' '
				} else {
					inSuppression = false
				}
			}
		} else if picCh == '9' {
			if inSuppression {
				inSuppression = false
			}
		} else if picCh == ',' {
			if inSuppression {
				output[i] = ' '
			}
		}
	}
	return string(output)
}

func applyOverflow(d decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	if d.IsZero() {
		return d
	}
	sign := d.Sign()
	abs := d
	if sign < 0 {
		abs = d.Neg()
	}
	scaled := abs.Shift(int32(scale)).Truncate(0)
	total := intDigits + scale
	mod := pow10Decimal(total)
	if scaled.Cmp(mod) >= 0 {
		scaled = scaled.Mod(mod)
	}
	result := scaled.Shift(int32(-scale))
	if sign < 0 {
		result = result.Neg()
	}
	return result
}

func parseDecimalField(s string, scale int) decimal.Decimal {
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.NewFromInt(0)
	}
	d, err := decimal.NewFromString(t)
	if err != nil {
		var b strings.Builder
		for _, ch := range t {
			if ch >= '0' && ch <= '9' {
				b.WriteRune(ch)
			} else if ch == '-' {
				b.WriteRune(ch)
			}
		}
		ts := b.String()
		if ts == "" {
			return decimal.NewFromInt(0)
		}
		d, _ = decimal.NewFromString(ts)
	}
	return d.Shift(int32(-scale))
}

func parseIntField(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	v, err := strconv.ParseInt(t, 10, 64)
	if err == nil {
		return v
	}
	var b strings.Builder
	for _, ch := range t {
		if ch >= '0' && ch <= '9' {
			b.WriteRune(ch)
		} else if ch == '-' {
			b.WriteRune(ch)
		}
	}
	ts := b.String()
	if ts == "" {
		return 0
	}
	v, _ = strconv.ParseInt(ts, 10, 64)
	return v
}

func formatCount(c int64) string {
	return fmt.Sprintf("%05d", c)
}

// paragraph functions

func OpenLoanFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		// treat missing as empty to still produce summary
		if os.IsNotExist(err) {
			loanFile = nil
			scanner = nil
			return
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	loanFile = f
	scanner = bufio.NewScanner(f)
	// allow larger lines
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 1024*1024)
}

func CloseLoanFile() {
	if loanFile != nil {
		loanFile.Close()
	}
}

func ReadPara() {
	if scanner == nil {
		WsEofFlag = "Y"
		return
	}
	if scanner.Scan() {
		line := scanner.Text()
		if len(line) < 21 {
			line = line + strings.Repeat(" ", 21-len(line))
		} else if len(line) > 21 {
			line = line[:21]
		}
		loanRec.LrAcct = line[0:6]
		loanRec.LrPrincipal = parseDecimalField(line[6:15], 2)
		loanRec.LrRate = parseDecimalField(line[15:19], 2)
		loanRec.LrYears = parseIntField(line[19:21])
	} else {
		if err := scanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	// COMPUTE WS-INTEREST ROUNDED = LR-PRINCIPAL * LR-RATE * LR-YEARS / 100
	yearsDec := decimal.NewFromInt(loanRec.LrYears)
	raw := loanRec.LrPrincipal.Mul(loanRec.LrRate).Mul(yearsDec).Shift(-2)
	rounded := raw.Round(2)
	WsInterest = applyOverflow(rounded, 9, 2)

	// ADD WS-INTEREST TO WS-TOTAL
	sum := WsTotal.Add(WsInterest)
	// truncate to scale of WS-TOTAL (2)
	sumTrunc := sum.Truncate(2)
	WsTotal = applyOverflow(sumTrunc, 11, 2)

	// ADD 1 TO WS-COUNT
	WsCount = (WsCount + 1) % 100000

	// MOVE LR-PRINCIPAL TO WS-PRIN-ED
	WsPrinEd = formatEdited(loanRec.LrPrincipal, "Z,ZZZ,ZZ9.99")
	// MOVE WS-INTEREST TO WS-INT-ED
	WsIntEd = formatEdited(WsInterest, "ZZZ,ZZZ,ZZ9.99")

	// DISPLAY LR-ACCT " " WS-PRIN-ED " " WS-INT-ED
	fmt.Printf("%s %s %s\n", loanRec.LrAcct, WsPrinEd, WsIntEd)

	// PERFORM READ-PARA
	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	fmt.Printf("RECORDS: %s\n", formatCount(WsCount))
	fmt.Printf("TOTAL INTEREST: %s\n", WsTotalEd)
}

func MainPara() {
	OpenLoanFile()
	ReadPara()
	for !inputDone() {
		ProcessPara()
	}
	CloseLoanFile()
	SummaryPara()
}

func main() {
	MainPara()
}
